import * as vscode from 'vscode';
import * as path from 'path';
import * as fs from 'fs';
import { ChildProcess, spawn } from 'child_process';

let serverProcess: ChildProcess | undefined;
let outputChannel: vscode.OutputChannel | undefined;

export async function ensureServerRunning(context: vscode.ExtensionContext): Promise<string> {
  const serverDir = path.join(context.extensionPath, '..', 'server');
  const portFilePath = path.join(serverDir, '.canopy', 'server.port');

  // If port file exists, check if server is actually reachable
  if (fs.existsSync(portFilePath)) {
    const port = fs.readFileSync(portFilePath, 'utf-8').trim();
    const baseUrl = `http://localhost:${port}`;
    try {
      const res = await fetch(`${baseUrl}/results?workspacePath=/healthcheck`, { signal: AbortSignal.timeout(2000) });
      // Server is running (404 is fine — means server is up but no results yet)
      if (res.status === 404 || res.ok) {
        return baseUrl;
      }
    } catch {
      // Server not reachable — delete stale port file and respawn
      fs.unlinkSync(portFilePath);
    }
  }

  // Ensure server is built
  const serverEntry = path.join(serverDir, 'dist', 'index.js');
  if (!fs.existsSync(serverEntry)) {
    throw new Error('Server not built. Run `npm run build` in the server/ directory first.');
  }

  // Create output channel for server logs
  if (!outputChannel) {
    outputChannel = vscode.window.createOutputChannel('Canopy Server');
  }

  // Spawn server
  serverProcess = spawn('node', ['dist/index.js'], {
    cwd: serverDir,
    detached: false,
    stdio: 'pipe',
    env: { ...process.env }
  });

  serverProcess.stdout?.on('data', (data: Buffer) => {
    outputChannel?.appendLine(data.toString().trim());
  });

  serverProcess.stderr?.on('data', (data: Buffer) => {
    outputChannel?.appendLine(`[stderr] ${data.toString().trim()}`);
  });

  serverProcess.on('exit', (code) => {
    if (code !== null && code !== 0) {
      vscode.window.showErrorMessage(`Canopy server exited with code ${code}. Check Output > Canopy Server for details.`);
    }
    serverProcess = undefined;
  });

  // Watch for port file using fs.watch instead of polling
  const baseUrl = await watchForPortFile(portFilePath, 15000, serverProcess);
  return baseUrl;
}

export async function getBaseUrl(context: vscode.ExtensionContext): Promise<string> {
  const serverDir = path.join(context.extensionPath, '..', 'server');
  const portFilePath = path.join(serverDir, '.canopy', 'server.port');

  if (!fs.existsSync(portFilePath)) {
    throw new Error('Server port file not found. Is the server running?');
  }

  const port = fs.readFileSync(portFilePath, 'utf-8').trim();
  return `http://localhost:${port}`;
}

export function stopServer(): void {
  if (serverProcess) {
    serverProcess.kill('SIGTERM');
    serverProcess = undefined;
  }
}

// Uses fs.watch (kernel-level inotify/FSEvents/kqueue) instead of repeated polling
// with setTimeout. This eliminates CPU wake-ups every 500 ms and lets the OS notify
// the process exactly once when the port file is created, reducing energy usage
// proportionally to (timeoutMs / intervalMs) avoided timer callbacks.
async function watchForPortFile(portFilePath: string, timeoutMs: number, proc: ChildProcess): Promise<string> {
  // Resolve immediately if the file already exists before the watcher is set up
  if (fs.existsSync(portFilePath)) {
    const port = await fs.promises.readFile(portFilePath, 'utf-8');
    return `http://localhost:${port.trim()}`;
  }

  return new Promise<string>((resolve, reject) => {
    // Watch the parent directory because the file does not exist yet
    const watchDir = path.dirname(portFilePath);
    const fileName = path.basename(portFilePath);

    // Ensure the directory exists before watching it
    fs.mkdirSync(watchDir, { recursive: true });

    let watcher: fs.FSWatcher | undefined;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const cleanup = () => {
      watcher?.close();
      if (timer !== undefined) {
        clearTimeout(timer);
      }
    };

    const tryResolve = async () => {
      try {
        if (!fs.existsSync(portFilePath)) {
          return;
        }
        const port = (await fs.promises.readFile(portFilePath, 'utf-8')).trim();
        if (!port) {
          // File exists but not yet fully written; wait for the next event
          return;
        }
        cleanup();
        resolve(`http://localhost:${port}`);
      } catch {
        // File may have been partially written; the next watch event will retry
      }
    };

    try {
      watcher = fs.watch(watchDir, async (event, changedFile) => {
        if (changedFile === fileName && (event === 'rename' || event === 'change')) {
          await tryResolve();
        }
      });
    } catch (err) {
      cleanup();
      reject(new Error(`Unable to watch directory ${watchDir}: ${(err as Error).message}`));
      return;
    }

    watcher.on('error', (err) => {
      cleanup();
      reject(new Error(`File watcher error: ${err.message}`));
    });

    // Abort if the spawned process exits before writing the port file
    proc.on('exit', (code) => {
      if (!fs.existsSync(portFilePath)) {
        cleanup();
        reject(new Error(`Server process exited (code ${code}) before writing port file`));
      }
    });

    // Hard timeout as a safety net
    timer = setTimeout(() => {
      cleanup();
      reject(new Error('Server failed to start within 15 seconds'));
    }, timeoutMs);
  });
}

